2	package darksafe
3	
4	// Subject is an identity that can request access to a resource.
5	type Subject struct {
6		ID       string
7		Kind     string   // "user", "service", "external"
8		Roles    []string
9		Disabled bool
10	}
11	
12	// Resource is a protected object with a scope path.
13	type Resource struct {
14		ID    string
15		Scope string // e.g. "org/payments/ledger"
16	}
17	
18	// Decision explains one access evaluation.
19	type Decision struct {
20		Allowed bool
21		Reason  string
22		Matched []string
23	}
24	
25	// Access evaluates a request and always returns an explanation.
26	func Access(subject Subject, resource Resource, action string) Decision {
27		if subject.Disabled {
28			return Decision{Allowed: false, Reason: "subject is disabled"}
29		}
30		if subject.ID == "" || resource.ID == "" || action == "" {
31			return Decision{Allowed: false, Reason: "incomplete request"}
32		}
33		needed := action + ":" + resource.Scope
34		for _, role := range subject.Roles {
35			if role == "owner" || role == resource.Scope+":"+action {
36				return Decision{Allowed: true, Reason: "role grants " + needed, Matched: []string{role}}
37			}
38		}
39		return Decision{Allowed: false, Reason: "no role grants " + needed}
40	}
